test.describe("delete and restore draft", () => {
  test("delete and restore draft", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-02-01", "to": "2026-02-10"})).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "30.00", "date": "2026-02-05"}));
    const c_ada_3 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "40.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_0, "delete")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "delete")).toBe(false);
    expect(await ui.claimAction(pg_uma, c_ada_2, "delete")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_3, "delete")).toBe(true);
    expect(await ui.editClaim(pg_uma, c_ada_0, {"amount": "11.00"})).toBe(false);
