94	    /** Make the claims, settled (or left PENDING) by one bulk settle, the sheet's next settle batch,
95	     * returning them with its number, in the order given; records BATCH_SETTLED with the batch's number,
96	     * how many claims it has and the frozen figures of those SETTLED added up. */
97	    @Transactional
98	    public List<Claim> settleBatch(String sheetId, String user, List<Claim> settled) {
99	        int batch = sheets.nextSettleBatch(sheetId);
100	        List<Claim> batched = settled.stream().map(c -> {
101	            Claim claim = claims.lockByIdAndSheetId(c.getId(), sheetId).orElseThrow(ClaimNotFoundException::new);
102	            claim.setSettleBatch(batch);
