183	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
184	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
185	        refuseClosed(sheetId, claim.getDueBy());
186	        refuseClosed(sheetId, holidays.dueBy(sheetId, dated, claim.getTerms()));
