314	    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
315	     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
316	     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
317	     * when the claim is dated in a closed period. */
318	    @Transactional
319	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
320	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
321	        refuseClosed(sheetId, claim.getDueBy());
322	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
323	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
324	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
325	                .orElseThrow(PersonNotFoundException::new);
326	        RollupService.Snapshot before = rollup.snapshot(sheetId);
327	        claim.setDeferredUntil(until);
328	        claims.flush();
329	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
330	        rollup.recordSince(sheetId, user, before);
331	        return claim;
332	    }
333	
334	    /** Remind an OPEN or PENDING claim: a reminder is written and the claim is reminded on the sheet's
335	     * today. Refused unless the claim is OPEN or PENDING, when it was already reminded on the sheet's
336	     * today, and when its due-by is in a closed period. */
337	    @Transactional
338	    public Claim remind(String sheetId, String user, long claimId) {
339	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
340	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
341	            throw new ClaimStatusChangeException();
342	        }
343	        LocalDate today = sheets.today(sheetId);
344	        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
345	        refuseClosed(sheetId, claim.getDueBy());
346	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
347	                .orElseThrow(PersonNotFoundException::new);
348	        claim.setRemindedOn(today);
349	        claims.flush();
350	        record("REMIND", user, person, claim, claim.getNumber());
351	        return claim;
352	    }
353	
354	    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed,
355	     * so its period and number stay too, and a figure a statement bound it to stays bound. Refused when the
356	     * user is not a steward, unless the claim is OPEN or PENDING, when its due-by is in a closed period,
357	     * and when the new date is after its person's retirement date. */
358	    @Transactional
359	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
360	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
361	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
362	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
363	            throw new ClaimStatusChangeException();
364	        }
365	        refuseClosed(sheetId, claim.getDueBy());
366	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
367	                .orElseThrow(PersonNotFoundException::new);
368	        person.requireClaimable(date);
369	        RollupService.Snapshot before = rollup.snapshot(sheetId);
370	        LocalDate old = claim.getDate();
371	        claim.setDate(date);
372	        claims.flush();
373	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
374	        rollup.recordSince(sheetId, user, before);
375	        return claim;
376	    }
377	
378	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
379	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
380	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
381	     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
382	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
383	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
384	     * in a closed period. Both claims are returned, the original first. */
385	    @Transactional
386	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
387	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
388	        refuseClosed(sheetId, claim.getDueBy());
389	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
390	            throw new ClaimStatusChangeException();
391	        }
392	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
393	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
394	                .orElseThrow(PersonNotFoundException::new);
395	        RollupService.Snapshot before = rollup.snapshot(sheetId);
396	        claim.setAmount(claim.getAmount().subtract(amount));
397	        claim.unbind();
398	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
399	        int terms = termsOf(sheetId, person, claim.getDate());
400	        split.fixTerms(claim.getDate(), terms);
401	        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
402	        refuseClosed(sheetId, split.getDueBy());
403	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
404	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
405	        split.setStatus(ClaimStatus.OPEN);
406	        split.setNumber(nextNumber(sheetId, split.getDueBy()));
407	        split.setOpenedBy(user);
408	        split.setSplitFrom(claim.getNumber());
409	        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
410	        split = claims.saveAndFlush(split);
411	        log(user, person, split);
412	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
413	        record("CLAIM_OPENED", user, person, split, split.getNumber());
414	        rollup.recordSince(sheetId, user, before);
415	        return List.of(claim, split);
416	    }
417	
418	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
419	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
420	     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
421	     * has no proofs and that due is above the proof threshold in force on its date. */
422	    @Transactional
423	    public Claim approve(String sheetId, String user, long claimId) {
424	        Claim claim = lockPending(sheetId, user, claimId);
425	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
426	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
427	                .orElseThrow(PersonNotFoundException::new);
428	        RollupService.Snapshot before = rollup.snapshot(sheetId);
429	        BigDecimal figure = rollup.dueOf(claim, person);
430	        BigDecimal due = rollup.liveDueOf(claim, figure);
431	        refuseUnproved(claim, person, due);
432	        claim.setSettledDue(due);
433	        claim.setStatus(ClaimStatus.SETTLED);
434	        claims.flush();
435	        log(user, person, claim);
436	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
437	        notifyWatchers(user, person, claim);
438	        rollup.recordSince(sheetId, user, before);
439	        return claim;
440	    }
441	
442	    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID, and when it is
443	     * dated in a closed period. */
444	    @Transactional
445	    public Claim addProof(String sheetId, String user, long claimId) {
446	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
447	        refuseClosed(sheetId, claim.getDueBy());
448	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
449	            throw new ClaimStatusChangeException();
450	        }
451	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
452	                .orElseThrow(PersonNotFoundException::new);
453	        claim.addProof();
454	        claims.flush();
455	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
456	        return claim;
457	    }
458	
459	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
460	     * by its person's last statement if that statement included it. Refused unless the claim is
461	     * PENDING, and when the user is not a steward. */
462	    @Transactional
463	    public Claim reject(String sheetId, String user, long claimId, String reason) {
464	        Claim claim = lockPending(sheetId, user, claimId);
465	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
466	                .orElseThrow(PersonNotFoundException::new);
467	        RollupService.Snapshot before = rollup.snapshot(sheetId);
468	        claim.setStatus(ClaimStatus.OPEN);
469	        claims.flush();
470	        log(user, person, claim);
471	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
472	        rollup.recordSince(sheetId, user, before);
473	        return claim;
474	    }
475	
476	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
477	     * date but, unless a draft (which has no number), is given the next number in the sequence it is
478	     * numbered in (as when opened now), its old number never used again; it loses
479	     * any figure a statement bound it to (it is live again until its new person's next statement), and is listed as its new person's newest claim. Refused when the user's
480	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
481	     * own person) or already belongs to the person, when it is dated in a closed period, and when it
482	     * is dated after the new person's retirement date. */
483	    @Transactional
484	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
485	        return move(sheetId, user, claimId, personId, false);
486	    }
487	
488	    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
489	     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
490	     * and recorded). */
491	    @Transactional
492	    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
493	        return move(sheetId, user, claimId, personId, true);
494	    }
495	
496	    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
497	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
498	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
499	        refuseClosed(sheetId, claim.getDueBy());
500	        ClaimStatus status = claim.getStatus();
501	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
502	                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
503	            throw new ClaimReassignException();
504	        }
505	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
506	                .orElseThrow(PersonNotFoundException::new);
507	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
508	        to.requireClaimable(claim.getDate());
509	        RollupService.Snapshot before = rollup.snapshot(sheetId);
510	        claim.setPersonId(to.getId());
511	        claim.unbind();
512	        if (claim.getNumber() != null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
513	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
514	        claims.flush();
515	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
516	        rollup.recordSince(sheetId, user, before);
517	        return claim;
518	    }
519	
520	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
521	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
522	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
523	     * steward, and when it is dated in a closed period. */
524	    @Transactional
525	    public Claim resettle(String sheetId, String user, long claimId) {
526	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
527	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
528	        refuseClosed(sheetId, claim.getDueBy());
529	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
530	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
531	                .orElseThrow(PersonNotFoundException::new);
532	        RollupService.Snapshot before = rollup.snapshot(sheetId);
533	        BigDecimal old = claim.getSettledDue();
534	        BigDecimal due = rollup.openShownOf(claim, person);
535	        claim.setSettledDue(due);
536	        claims.flush();
537	        log(user, person, claim);
538	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
539	        notifyWatchers(user, person, claim);
540	        rollup.recordSince(sheetId, user, before);
541	        return claim;
542	    }
543	
544	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
545	     * 7 days after the date its status log first shows it SETTLED. */
546	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
547	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
548	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
549	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
550	                .map(ClaimLog::getDate)
551	                .findFirst()
552	                .orElseThrow(ClaimStatusChangeException::new);
553	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
554	    }
555	
556	    /** The PENDING claim, locked, for a steward to approve or reject. */
557	    private Claim lockPending(String sheetId, String user, long claimId) {
558	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
559	        refuseClosed(sheetId, claim.getDueBy());
560	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
561	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
562	        return claim;
563	    }
564	
565	    private static String dueText(BigDecimal due) {
566	        return due == null ? "n/a" : due.toPlainString();
567	    }
568	
569	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
570	     * (see {@link RollupService#figureOf}). */
571	    public BigDecimal figureOf(Claim claim, Person person) {
572	        return rollup.figureOf(claim, person);
573	    }
574	
575	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
576	     * no figure (see {@link RollupService#shownOf}). */
577	    public BigDecimal shownOf(Claim claim, Person person) {
578	        return rollup.shownOf(claim, person);
579	    }
580	
581	    /** Keep each of the claim's tags among those ever used on its sheet. */
582	    public void keepTags(Claim claim) {
583	        for (String tag : claim.getTags()) {
584	            SheetTag.Key key = new SheetTag.Key(claim.getSheetId(), tag);
585	            if (!tagRepository.existsById(key)) tagRepository.save(new SheetTag(claim.getSheetId(), tag));
586	        }
587	    }
588	
589	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
590	     * it shows now. */
591	    private void log(String user, Person person, Claim claim) {
592	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
593	                rollup.shownOf(claim, person)));
594	    }
595	
596	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
597	     * then any {@code extra} fields. */
598	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
599	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
600	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
601	                "date=" + claim.getDate()));
602	        if (number != null) fields.add("number=" + number);
603	        fields.addAll(List.of(extra));
604	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
605	    }
606	
607	    /** Notify each user watching the person, in the order they started watching, that the claim was
608	     * settled, approved or re-settled. */
609	    private void notifyWatchers(String user, Person person, Claim claim) {
610	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
611	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
612	                    "number=" + claim.getNumber());
613	        }
614	    }
615	
616	    /** The number a claim due by {@code date} is given when opened now: within the period containing
617	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
618	     * period, otherwise the next sheet-wide number. */
619	    public String nextNumber(String sheetId, LocalDate date) {
620	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
621	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
622	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
623	                .findFirst()
624	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
625	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
626	    }
627	
628	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
629	     * the user is a clerk and the due is above the sheet's clerk limit. */
630	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
631	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
632	        BigDecimal limit = settings.clerkLimit(sheetId);
633	        return limit != null && due.compareTo(limit) > 0;
634	    }
635	
636	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
637	     * due is above the proof threshold in force on its date: its person's grade's own then, else the sheet's
638	     * (a due that is n/a is within any threshold). */
639	    private void refuseUnproved(Claim claim, Person person, BigDecimal due) {
640	        if (due == null || claim.getProofs() > 0) return;
641	        BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
642	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
643	    }
644	
645	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
646	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
647	    private void refuseNoteless(Claim claim, BigDecimal due) {
648	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
649	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
650	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
651	    }
652	
653	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
654	     * the person, and a claim that names one without being a correction. */
655	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
656	        if (amount.signum() >= 0) {
657	            if (corrects != null) throw new ClaimCorrectionException();
658	            return;
659	        }
660	        if (corrects == null) throw new ClaimCorrectionException();
661	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
662	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
663	                .orElseThrow(ClaimCorrectionException::new);
664	    }
665	
666	    /** Refuse the external reference {@code ref} when a claim on the sheet other than {@code claimId} has
667	     * it, compared without regard to case. */
668	    private void refuseRefTaken(String sheetId, Long claimId, String ref) {
669	        if (ref == null) return;
670	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
671	                .filter(other -> !other.getId().equals(claimId))
672	                .ifPresent(other -> {
673	                    throw new ClaimRefTakenException();
674	                });
675	    }
676	
677	    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
678	    private void refuseClosed(String sheetId, LocalDate date) {
679	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
680	    }
681	
682	    private static String noteOf(String note) {
683	        return note == null ? "" : note.trim();
684	    }
685	
686	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
687	     * of their grade in force on that date, else the sheet's then. */
688	    private int termsOf(String sheetId, Person person, LocalDate date) {
689	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
690	    }
691	}
